const routes = {
  '/people': ['افراد','فهرست افراد'], '/people/create':['افراد','ثبت فرد'], '/people/detail':['افراد','پرونده فرد'], '/people/edit':['افراد','ویرایش فرد'],
  '/fleet/vehicles':['ناوگان','خودروهای سازمان'], '/fleet/vehicles/create':['ناوگان','ثبت خودرو'], '/fleet/vehicles/detail':['ناوگان','پرونده خودرو'], '/fleet/vehicles/edit':['ناوگان','ویرایش خودرو'],
  '/fleet/insurances':['ناوگان','بیمه‌ها'], '/fleet/insurances/create':['ناوگان','ثبت بیمه'], '/fleet/insurances/edit':['ناوگان','ویرایش بیمه'], '/fleet/catalogs':['ناوگان','کاتالوگ خودروها'],
  '/drivers':['رانندگان','فهرست رانندگان'], '/drivers/create':['رانندگان','ثبت راننده'], '/drivers/profile':['رانندگان','پرونده راننده'],
  '/trips':['سفرها','مرکز سفرها'], '/trips/requests':['سفرها','فهرست درخواست‌ها'], '/trips/create':['سفرها','ثبت درخواست سفر'], '/trips/handling':['سفرها','رسیدگی به سفرها'], '/trips/workspace':['سفرها','پرونده سفر'], '/trips/voucher':['سفرها','برگه مأموریت']
};
const demoTrips = [
  {no:'TR-1405-0241',by:'واحد منابع انسانی',person:'مریم احمدی',count:2,date:'۱۴۰۵/۰۷/۰۲',time:'۰۹:۳۰',from:'ساختمان مرکزی',to:'فرودگاه مهرآباد',status:'New',priority:'امروز'},
  {no:'TR-1405-0240',by:'واحد پشتیبانی',person:'علی رضایی',count:1,date:'۱۴۰۵/۰۷/۰۲',time:'۱۱:۱۵',from:'انبار غرب',to:'ساختمان مرکزی',status:'Assigned',priority:'امروز'},
  {no:'TR-1405-0239',by:'واحد مالی',person:'سارا محمدی',count:3,date:'۱۴۰۵/۰۷/۰۱',time:'۰۸:۰۰',from:'دفتر مرکزی',to:'شهرک صنعتی',status:'InProgress',priority:'در مسیر'},
  {no:'TR-1405-0238',by:'واحد خدمات',person:'رضا کریمی',count:1,date:'۱۴۰۵/۰۶/۳۱',time:'۱۴:۰۰',from:'دفتر مرکزی',to:'میدان آزادی',status:'Completed',priority:'انجام‌شده'},
  {no:'TR-1405-0237',by:'واحد اداری',person:'نرگس عباسی',count:2,date:'۱۴۰۵/۰۶/۳۰',time:'۱۰:۰۰',from:'ساختمان مرکزی',to:'ترمینال غرب',status:'Cancelled',priority:'لغوشده'}
];
const people=[{name:'مریم احمدی',code:'۰۰۷۹۸۳۴۵۶۱',personnel:'۱۰۴۲',phone:'۰۹۱۲•••۴۵۶۷',active:true},{name:'علی رضایی',code:'۰۰۸۶۴۱۲۳۵۹',personnel:'۱۰۱۸',phone:'۰۹۱۲•••۲۲۸۱',active:true},{name:'سارا محمدی',code:'۰۰۶۳۲۸۷۱۹۴',personnel:'۱۰۶۴',phone:'۰۹۳۵•••۸۳۱۰',active:true},{name:'رضا کریمی',code:'۰۰۱۷۸۳۴۵۲۶',personnel:'۱۰۳۱',phone:'۰۹۱۹•••۴۴۷۰',active:false}];
const vehicles=[{name:'پژو ۲۰۷',plate:'۴۵ | ۱۲۳ ب ۶۷',type:'سواری',fuel:'بنزین',status:'فعال',insurance:'۱۴۰۵/۱۱/۲۳'},{name:'تویوتا هایلوکس',plate:'۲۱ | ۸۴۵ ص ۱۲',type:'وانت',fuel:'گازوئیل',status:'در سرویس',insurance:'۱۴۰۵/۰۸/۱۷'},{name:'سمند سورن',plate:'۷۹ | ۴۵۲ ج ۳۳',type:'سواری',fuel:'بنزین',status:'فعال',insurance:'۱۴۰۵/۰۷/۱۵'},{name:'ون وانا',plate:'۱۱ | ۳۲۶ م ۴۴',type:'ون',fuel:'گازوئیل',status:'غیرفعال',insurance:'۱۴۰۵/۰۶/۲۹'}];
const drivers=[{name:'علی رضایی',license:'پایه ۲',vehicle:'پژو ۲۰۷',status:'آماده',assignments:'۸'},{name:'رضا کریمی',license:'پایه ۱',vehicle:'تویوتا هایلوکس',status:'در مأموریت',assignments:'۱۲'},{name:'حسین زمانی',license:'پایه ۲',vehicle:'بدون خودرو',status:'بدون تخصیص',assignments:'۵'}];
const statusLabel={New:'جدید',Assigned:'تخصیص‌یافته',InProgress:'در حال اجرا',Completed:'تکمیل‌شده',Cancelled:'لغوشده'};
const statusTone={New:'blue',Assigned:'amber',InProgress:'blue',Completed:'green',Cancelled:'red'};
let state={route:'/trips/handling',theme:localStorage.getItem('fleet-concept-theme')||'light',tab:'details',tripIndex:0,search:'',filter:'all',wizard:0,catalog:'مدل خودرو',mobile:false};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('fa-IR').format(n);
const badge=(text,tone='neutral')=>`<span class="badge ${tone}"><span class="circle"></span>${esc(text)}</span>`;
const button=(label,action,kind='')=>`<button class="btn ${kind}" data-action="${action}">${label}</button>`;
const link=(label,route,kind='')=>`<a class="btn ${kind}" href="#${route}">${label}</a>`;
const plate=value=>`<span class="plate">${esc(value)}</span>`;
const metric=(label,value,icon,detail='')=>`<div class="metric"><div><small>${label}</small><strong>${value}</strong>${detail?`<small>${detail}</small>`:''}</div><span class="glyph">${icon}</span></div>`;
const panel=(title,body,aside='',subtitle='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<small>${subtitle}</small>`:''}</div>${aside}</div>${body}</section>`;
const head=(kicker,title,description,actions='')=>`<div class="page-head"><div><div class="page-kicker">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${actions}</div></div>`;
const field=(label,value,cls='')=>`<div class="field ${cls}"><span class="field-label">${label}</span><span class="value">${value}</span></div>`;
const input=(label,placeholder,value='',type='text',cls='')=>`<div class="field ${cls}"><label>${label}<input type="${type}" value="${esc(value)}" placeholder="${placeholder}"></label></div>`;
function nav(){const path=state.route; const item=(name,href,symbol,child=false,count='')=>`<a class="nav-link ${path===href||(!child&&path.startsWith(href+'/'))?'active':''}" href="#${href}"><span class="nav-symbol">${symbol}</span><span>${name}</span>${count?`<span class="count">${count}</span>`:''}</a>`;$('#side-nav').innerHTML=`<div class="nav-caption">مدیریت عملیات</div>${item('افراد','/people','♧')}${item('ناوگان','/fleet/vehicles','▣')}<div class="nav-sub">${item('خودروهای سازمان','/fleet/vehicles','•',true)}${item('بیمه‌ها','/fleet/insurances','•',true)}${item('کاتالوگ خودروها','/fleet/catalogs','•',true)}</div>${item('رانندگان','/drivers','◉')}${item('سفرها','/trips','↗',false,fmt(demoTrips.filter(x=>x.status==='New').length))}<div class="nav-sub">${item('ثبت درخواست','/trips/create','•',true)}${item('فهرست درخواست‌ها','/trips/requests','•',true)}${item('رسیدگی به سفرها','/trips/handling','•',true,fmt(demoTrips.filter(x=>x.status==='New').length))}</div>`;}
function setTheme(){document.documentElement.dataset.theme=state.theme;$('#theme-icon').textContent=state.theme==='light'?'☾':'☀';$('#theme-label').textContent=state.theme==='light'?'تاریک':'روشن';localStorage.setItem('fleet-concept-theme',state.theme)}
function render(){state.route=decodeURI(location.hash.slice(1))||'/trips/handling';if(!routes[state.route])state.route='/trips/handling';const [section,label]=routes[state.route];$('#breadcrumbs').innerHTML=`<span>FleetManagement</span><span>‹</span><span>${section}</span><span>‹</span><b>${label}</b>`;nav();setTheme();const content=({
 '/people':peopleList,'/people/create':()=>entityForm('person',false),'/people/detail':personDetail,'/people/edit':()=>entityForm('person',true),
 '/fleet/vehicles':vehicleList,'/fleet/vehicles/create':()=>entityForm('vehicle',false),'/fleet/vehicles/detail':vehicleDetail,'/fleet/vehicles/edit':()=>entityForm('vehicle',true),
 '/fleet/insurances':insuranceList,'/fleet/insurances/create':()=>entityForm('insurance',false),'/fleet/insurances/edit':()=>entityForm('insurance',true),'/fleet/catalogs':catalogs,
 '/drivers':driverList,'/drivers/create':()=>entityForm('driver',false),'/drivers/profile':driverProfile,
 '/trips':tripsLanding,'/trips/requests':()=>tripList(false),'/trips/create':wizard,'/trips/handling':()=>tripList(true),'/trips/workspace':workspace,'/trips/voucher':voucher
})[state.route]();$('#view').innerHTML=content;document.title=`${label} | کانسپت FleetManagement`;$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show');window.scrollTo({top:0,behavior:'instant'});}
function filtered(items,fields){const q=state.search.trim().toLowerCase();return items.filter(x=>!q||fields.some(f=>String(x[f]||'').toLowerCase().includes(q)))}
function toolbar(placeholder,showFilter=false){return `<div class="toolbar"><div class="search"><input data-search aria-label="جست‌وجو" placeholder="${placeholder}" value="${esc(state.search)}"></div>${showFilter?`<select class="filter" data-filter aria-label="فیلتر وضعیت"><option value="all">همه وضعیت‌ها</option>${Object.entries(statusLabel).map(([k,v])=>`<option value="${k}" ${state.filter===k?'selected':''}>${v}</option>`).join('')}</select>`:''}<button class="btn subtle" data-action="filter-info">☷ فیلترها</button></div>`}
function tripRows(items){return items.map(t=>{const i=demoTrips.indexOf(t);return `<tr><td><a class="table-link" href="#/trips/workspace" data-trip="${i}">${t.no}</a><small>${t.by}</small></td><td><b>${t.person}</b><small>${fmt(t.count)} مسافر</small></td><td>${t.date}<small>ساعت ${t.time}</small></td><td>${t.from}<small>به ${t.to}</small></td><td>${badge(statusLabel[t.status],statusTone[t.status])}</td><td><a class="table-link" href="#/trips/workspace" data-trip="${i}">مشاهده پرونده ←</a></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">موردی با این جست‌وجو پیدا نشد.</td></tr>'}
function tripList(handling){let items=filtered(demoTrips,['no','person','by','from','to']);if(state.filter!=='all')items=items.filter(x=>x.status===state.filter);return `${head('سفرها',handling?'رسیدگی به سفرها':'فهرست درخواست‌ها',handling?'درخواست‌های جدید، تخصیص‌ها و سفرهای در حال اجرا را در یک صف ببینید.':'درخواست‌های ثبت‌شده و وضعیت هر پرونده را مرور کنید.',`${link('ثبت درخواست جدید','/trips/create','primary')}${link(handling?'همه درخواست‌ها':'صف رسیدگی',handling?'/trips/requests':'/trips/handling')}`)}<div class="grid metrics">${metric('درخواست جدید',fmt(demoTrips.filter(x=>x.status==='New').length),'□','نیازمند بررسی')}${metric('تخصیص‌یافته',fmt(demoTrips.filter(x=>x.status==='Assigned').length),'↗','آماده اعزام')}${metric('در حال اجرا',fmt(demoTrips.filter(x=>x.status==='InProgress').length),'◉','سفر فعال')}${metric('تکمیل‌شده',fmt(demoTrips.filter(x=>x.status==='Completed').length),'✓','در نمونهٔ امروز')}</div>${panel(handling?'صف رسیدگی':'همه درخواست‌ها',`${toolbar('شماره درخواست، مسافر یا واحد…',true)}<div class="table-wrap"><table><thead><tr><th>شماره / واحد</th><th>مسافر</th><th>زمان</th><th>مسیر</th><th>وضعیت</th><th></th></tr></thead><tbody>${tripRows(items)}</tbody></table></div>`,`${badge(fmt(items.length)+' مورد','neutral')}`)}<p class="subtext" style="margin:13px 3px">یک ردیف را باز کنید تا گردش کار و جزئیات قابل کلیک آن را ببینید.</p>`}
function tripsLanding(){return `${head('سفرها','مرکز سفرها','ثبت درخواست و رسیدگی به اعزام‌ها از اینجا شروع می‌شود.',link('درخواست سفر جدید','/trips/create','primary'))}<div class="grid metrics">${metric('درخواست جدید',fmt(demoTrips.filter(x=>x.status==='New').length),'□')}${metric('منتظر اعزام',fmt(demoTrips.filter(x=>x.status==='Assigned').length),'↗')}${metric('در مسیر',fmt(demoTrips.filter(x=>x.status==='InProgress').length),'◉')}${metric('تکمیل‌شده',fmt(demoTrips.filter(x=>x.status==='Completed').length),'✓')}</div><div class="grid split">${panel('برای ادامه کار',`<div class="panel-body">${[['ثبت درخواست سفر','زمان، مسافران و مقصد را ثبت کنید.','/trips/create','＋'],['رسیدگی به سفرها','درخواست‌های جدید و سفرهای فعال را بررسی کنید.','/trips/handling','↗'],['فهرست درخواست‌ها','سوابق و وضعیت همه پرونده‌ها را ببینید.','/trips/requests','▤']].map(([n,d,r,i])=>`<a class="list-row" href="#${r}"><span class="row-icon">${i}</span><span class="row-copy"><b>${n}</b><small>${d}</small></span><span class="arrow">←</span></a>`).join('')}</div>`)}${panel('درخواست‌های نزدیک',`<div class="panel-body">${demoTrips.slice(0,3).map((t,i)=>`<a class="list-row" href="#/trips/workspace" data-trip="${i}"><span class="row-copy"><b>${t.no} · ${t.person}</b><small>${t.from} ← ${t.to}</small></span>${badge(statusLabel[t.status],statusTone[t.status])}</a>`).join('')}</div>`)}</div>`}
function peopleList(){let rows=filtered(people,['name','code','personnel']);return `${head('افراد','فهرست افراد','افرادی که در سامانه به‌عنوان مسافر یا راننده استفاده می‌شوند.',link('ثبت فرد جدید','/people/create','primary'))}<div class="grid metrics">${metric('کل افراد',fmt(people.length),'♧')}${metric('فعال',fmt(people.filter(x=>x.active).length),'✓')}${metric('رانندگان',fmt(drivers.length),'◉')}${metric('پرونده نمونه',fmt(1),'▤')}</div>${panel('افراد ثبت‌شده',`${toolbar('نام، کد ملی یا شماره پرسنلی…')}<div class="table-wrap"><table><thead><tr><th>نام و نام خانوادگی</th><th>کد ملی</th><th>شماره پرسنلی</th><th>شماره تماس</th><th>وضعیت</th><th></th></tr></thead><tbody>${rows.map((p,i)=>`<tr><td><b>${p.name}</b></td><td>${p.code}</td><td>${p.personnel}</td><td>${p.phone}</td><td>${badge(p.active?'فعال':'غیرفعال',p.active?'green':'neutral')}</td><td><a class="table-link" href="#/people/detail">مشاهده ←</a></td></tr>`).join('')||'<tr><td colspan="6">موردی پیدا نشد.</td></tr>'}</tbody></table></div>`)}`}
function vehicleList(){let rows=filtered(vehicles,['name','plate','type']);return `${head('ناوگان','خودروهای سازمان','وضعیت خودرو، بیمه و اطلاعات شناسایی را در یک نگاه ببینید.',link('ثبت خودرو','/fleet/vehicles/create','primary'))}<div class="grid metrics">${metric('کل خودروها',fmt(vehicles.length),'▣')}${metric('آماده خدمت',fmt(vehicles.filter(x=>x.status==='فعال').length),'✓')}${metric('در سرویس',fmt(1),'⚙')}${metric('بیمه نزدیک انقضا',fmt(1),'!')}</div>${panel('فهرست خودروها',`${toolbar('مدل، پلاک یا نوع خودرو…')}<div class="table-wrap"><table><thead><tr><th>خودرو</th><th>پلاک</th><th>نوع / سوخت</th><th>وضعیت</th><th>پایان بیمه</th><th></th></tr></thead><tbody>${rows.map(v=>`<tr><td><b>${v.name}</b></td><td>${plate(v.plate)}</td><td>${v.type}<small>${v.fuel}</small></td><td>${badge(v.status,v.status==='فعال'?'green':v.status==='در سرویس'?'amber':'neutral')}</td><td>${v.insurance}</td><td><a class="table-link" href="#/fleet/vehicles/detail">جزئیات ←</a></td></tr>`).join('')||'<tr><td colspan="6">موردی پیدا نشد.</td></tr>'}</tbody></table></div>`)}`}
function insuranceList(){return `${head('ناوگان','بیمه‌های خودرو','اعتبار بیمه‌ها و خودروی مرتبط را یک‌جا مدیریت کنید.',link('ثبت بیمه','/fleet/insurances/create','primary'))}<div class="grid metrics">${metric('بیمه‌های ثبت‌شده','۳','▤')}${metric('معتبر','۲','✓')}${metric('نزدیک پایان','۱','!')}${metric('خودروهای تحت پوشش','۳','▣')}</div>${panel('فهرست بیمه‌ها',`${toolbar('پلاک، خودرو یا شماره بیمه…')}<div class="table-wrap"><table><thead><tr><th>خودرو و پلاک</th><th>نوع بیمه</th><th>شماره بیمه‌نامه</th><th>پایان اعتبار</th><th>وضعیت</th><th></th></tr></thead><tbody>${vehicles.slice(0,3).map((v,i)=>`<tr><td><b>${v.name}</b><small>${v.plate}</small></td><td>شخص ثالث</td><td>IN-۱۴۰۵-${['۲۴۱۸','۲۴۱۹','۲۴۲۰'][i]}</td><td>${v.insurance}</td><td>${badge(i===2?'نزدیک پایان':'معتبر',i===2?'amber':'green')}</td><td><a class="table-link" href="#/fleet/insurances/edit">ویرایش ←</a></td></tr>`).join('')}</tbody></table></div>`)}`}
function catalogs(){const names=['برند خودرو','مدل خودرو','نوع خودرو','نوع سوخت','وضعیت خودرو'];return `${head('ناوگان','کاتالوگ خودروها','داده‌های پایه برای ثبت و دسته‌بندی خودروهای سازمان.')}${`<div class="grid catalog-grid">${names.map((n,i)=>`<button class="catalog-card" data-catalog="${n}"><span class="glyph">${['◈','▣','▤','◉','✓'][i]}</span><span><b>${n}</b><small>${['۱۲ برند','۲۸ مدل','۴ نوع','۳ نوع سوخت','۵ وضعیت'][i]}</small></span><span class="arrow">←</span></button>`).join('')}</div>`}<div style="height:16px"></div>${panel(state.catalog,`<div class="toolbar"><div class="search"><input placeholder="جست‌وجو در ${state.catalog}…" aria-label="جست‌وجوی کاتالوگ"></div>${button('＋ افزودن مورد','sample-save','primary')}</div><div class="table-wrap"><table><thead><tr><th>نام</th><th>وضعیت</th><th>آخرین تغییر</th><th></th></tr></thead><tbody>${(state.catalog==='مدل خودرو'?['پژو ۲۰۷','سمند سورن','تویوتا هایلوکس','ون وانا']:state.catalog==='برند خودرو'?['ایران‌خودرو','تویوتا','فوتون']:state.catalog==='نوع سوخت'?['بنزین','گازوئیل','دوگانه‌سوز']:state.catalog==='نوع خودرو'?['سواری','وانت','ون','مینی‌بوس']:['فعال','در سرویس','غیرفعال']).map(n=>`<tr><td><b>${n}</b></td><td>${badge('فعال','green')}</td><td>۱۴۰۵/۰۶/۲۷</td><td><button class="btn subtle" data-action="sample-save">ویرایش</button></td></tr>`).join('')}</tbody></table></div>`,badge('داده نمونه','neutral'))}`}
function driverList(){return `${head('رانندگان','فهرست رانندگان','گواهینامه، تخصیص فعلی و تاریخچه فعالیت رانندگان.',link('افزودن راننده','/drivers/create','primary'))}<div class="grid metrics">${metric('رانندگان','۳','◉')}${metric('آماده اعزام','۱','✓')}${metric('در مأموریت','۱','↗')}${metric('نیازمند تخصیص','۱','!')}</div>${panel('رانندگان',`${toolbar('نام راننده، خودرو یا نوع گواهینامه…')}<div class="table-wrap"><table><thead><tr><th>راننده</th><th>گواهینامه</th><th>خودروی فعلی</th><th>سفرهای ثبت‌شده</th><th>وضعیت</th><th></th></tr></thead><tbody>${filtered(drivers,['name','vehicle','license']).map(d=>`<tr><td><b>${d.name}</b></td><td>${d.license}</td><td>${d.vehicle}</td><td>${d.assignments}</td><td>${badge(d.status,d.status==='آماده'?'green':d.status==='در مأموریت'?'blue':'amber')}</td><td><a class="table-link" href="#/drivers/profile">پرونده ←</a></td></tr>`).join('')}</tbody></table></div>`)}`}
function personDetail(){return `${head('افراد','پرونده مریم احمدی','مشخصات فرد و ارتباط او با درخواست‌های سفر.',`${link('بازگشت به فهرست','/people')}${link('ویرایش اطلاعات','/people/edit','primary')}`)}<div class="grid split">${panel('اطلاعات فرد',`<div class="panel-body"><div class="detail-top"><div class="detail-title"><span class="big-icon">م</span><div><h2>مریم احمدی</h2><small>شماره پرسنلی ۱۰۴۲</small></div></div>${badge('فعال','green')}</div><div class="field-grid">${field('کد ملی','۰۰۷۹۸۳۴۵۶۱')}${field('شماره پرسنلی','۱۰۴۲')}${field('شماره تماس','۰۹۱۲•••۴۵۶۷')}${field('شماره کارت','۲۵۸۴')}${field('وضعیت','فعال')}${field('تاریخ ثبت','۱۴۰۵/۰۲/۱۸')}</div></div>`)}${panel('سفرهای مرتبط',`<div class="panel-body"><a class="list-row" href="#/trips/workspace" data-trip="0"><span class="row-copy"><b>TR-1405-0241</b><small>ساختمان مرکزی ← فرودگاه مهرآباد</small></span>${badge('جدید','blue')}</a><a class="list-row" href="#/trips/workspace" data-trip="3"><span class="row-copy"><b>TR-1405-0238</b><small>دفتر مرکزی ← میدان آزادی</small></span>${badge('تکمیل‌شده','green')}</a></div>`)}</div>`}
function vehicleDetail(){const v=vehicles[0];return `${head('ناوگان','پرونده خودرو','اطلاعات خودرو، وضعیت سرویس و بیمه در یک صفحه.',`${link('بازگشت به خودروها','/fleet/vehicles')}${link('ویرایش خودرو','/fleet/vehicles/edit','primary')}`)}<div class="grid split">${panel(v.name,`<div class="panel-body"><div class="detail-top"><div class="detail-title"><span class="big-icon">▣</span><div><h2>${v.name}</h2><small>خودرو سازمانی · ${v.type}</small></div></div>${badge('فعال','green')}</div><div class="field-grid">${field('شماره پلاک',plate(v.plate))}${field('مدل','پژو ۲۰۷')}${field('برند','ایران‌خودرو')}${field('نوع خودرو',v.type)}${field('سوخت',v.fuel)}${field('بیمه تا',v.insurance)}</div></div>`)}${panel('وضعیت و ارتباطات',`<div class="panel-body"><div class="timeline"><div class="timeline-item"><b>بیمه شخص ثالث معتبر</b><p>پایان اعتبار: ${v.insurance}</p></div><div class="timeline-item"><b>تخصیص فعلی راننده</b><p>علی رضایی · از ۱۴۰۵/۰۶/۰۱</p></div><div class="timeline-item"><b>آخرین سفر ثبت‌شده</b><p>TR-1405-0240</p></div></div></div>`)}</div>`}
function driverProfile(){return `${head('رانندگان','پرونده علی رضایی','گواهینامه، خودروی فعلی و تاریخچه تخصیص‌ها.',link('بازگشت به رانندگان','/drivers'))}<div class="grid split">${panel('مشخصات راننده',`<div class="panel-body"><div class="detail-top"><div class="detail-title"><span class="big-icon">ع</span><div><h2>علی رضایی</h2><small>شماره پرسنلی ۱۰۱۸</small></div></div>${badge('آماده اعزام','green')}</div><div class="field-grid">${field('کد ملی','۰۰۸۶۴۱۲۳۵۹')}${field('نوع گواهینامه','پایه ۲')}${field('اعتبار گواهینامه','۱۴۰۷/۰۴/۰۲')}${field('شماره گواهینامه','۳۴۵۶۷۸۹')}${field('تاریخ صدور','۱۴۰۲/۰۴/۰۲')}${field('وضعیت','فعال')}</div></div>`)}${panel('تخصیص خودرو',`<div class="panel-body"><div class="info-note">تخصیص جاری تنها در بازه معتبر گواهینامه قابل استفاده است.</div><div class="list-row"><span class="row-icon">▣</span><span class="row-copy"><b>پژو ۲۰۷</b><small>${vehicles[0].plate} · از ۱۴۰۵/۰۶/۰۱</small></span>${badge('جاری','green')}</div><div class="list-row"><span class="row-copy"><b>سمند سورن</b><small>تخصیص پیشین · ۱۴۰۴/۱۱ تا ۱۴۰۵/۰۵</small></span>${badge('گذشته','neutral')}</div><div class="inline-actions" style="margin-top:15px">${button('تخصیص جدید','sample-save','primary')}${button('بستن تخصیص جاری','sample-save')}</div></div>`)}</div>`}
function entityForm(type,edit){const cfg={person:{section:'افراد',noun:'فرد',return:'/people',fields:input('نام','نام',edit?'مریم':'')+input('نام خانوادگی','نام خانوادگی',edit?'احمدی':'')+input('کد ملی','۱۰ رقم',edit?'۰۰۷۹۸۳۴۵۶۱':'')+input('شماره پرسنلی','شماره پرسنلی',edit?'۱۰۴۲':'')+input('شماره کارت','شماره کارت',edit?'۲۵۸۴':'')+input('شماره تماس','تلفن همراه',edit?'۰۹۱۲۳۴۵۶۷۸':'')},vehicle:{section:'ناوگان',noun:'خودرو',return:'/fleet/vehicles',fields:input('برند','جست‌وجوی برند…',edit?'ایران‌خودرو':'')+input('مدل','جست‌وجوی مدل…',edit?'پژو ۲۰۷':'')+input('نوع خودرو','نوع خودرو',edit?'سواری':'')+input('نوع سوخت','سوخت',edit?'بنزین':'')+input('پلاک','شماره پلاک',edit?'۴۵ | ۱۲۳ ب ۶۷':'')+input('وضعیت','وضعیت خودرو',edit?'فعال':'')},insurance:{section:'ناوگان',noun:'بیمه',return:'/fleet/insurances',fields:input('خودرو','خودرو را جست‌وجو کنید…',edit?'پژو ۲۰۷':'')+input('شماره بیمه‌نامه','شماره',edit?'IN-۱۴۰۵-۲۴۱۸':'')+input('نوع بیمه','نوع بیمه',edit?'شخص ثالث':'')+input('تاریخ شروع شمسی','۱۴۰۵/۰۱/۰۱',edit?'۱۴۰۴/۱۱/۲۳':'')+input('تاریخ پایان شمسی','۱۴۰۶/۰۱/۰۱',edit?'۱۴۰۵/۱۱/۲۳':'')},driver:{section:'رانندگان',noun:'راننده',return:'/drivers',fields:input('انتخاب فرد','نام یا شماره پرسنلی…')+input('شماره گواهینامه','شماره گواهینامه')+input('پایه گواهینامه','پایه ۱ / پایه ۲')+input('تاریخ صدور شمسی','۱۴۰۵/۰۱/۰۱')+input('تاریخ انقضا شمسی','۱۴۰۷/۰۱/۰۱')}}[type];return `${head(cfg.section,`${edit?'ویرایش':'ثبت'} ${cfg.noun}`,`چیدمان پیشنهادی فرم ${cfg.noun} با گروه‌بندی روشن و فضای خوانا.`,link('بازگشت',cfg.return))}<div class="grid split">${panel(`اطلاعات ${cfg.noun}`,`<div class="panel-body"><div class="field-grid">${cfg.fields}</div></div><div class="footer-actions"><span class="subtext">فیلدهای این صفحه برای نمایش طراحی هستند.</span><div class="inline-actions">${link('انصراف',cfg.return)}${button(edit?'ثبت تغییرات':'ثبت نمونه','sample-save','primary')}</div></div>`)}${panel('راهنمای ثبت',`<div class="panel-body"><div class="info-note">در پروژهٔ اصلی، اعتبارسنجی و قوانین تجاری از سمت برنامه و پایگاه داده اعمال می‌شوند. این صفحه فقط چیدمان را نشان می‌دهد.</div><div class="timeline" style="margin-top:21px"><div class="timeline-item"><b>فیلدهای مرتبط کنار هم</b><p>شناسایی، اطلاعات تکمیلی و وضعیت در بخش‌های خوانا.</p></div><div class="timeline-item"><b>خطا کنار فیلد</b><p>در نسخه اجرایی، متن دقیق خطا در همان محل نمایش داده می‌شود.</p></div></div></div>`)}</div>`}
function wizard(){const steps=['اطلاعات درخواست','مسافران و مسیر','بازبینی و ثبت'];const step=state.wizard;return `${head('سفرها','ثبت درخواست سفر','یک جریان کوتاه و مرحله‌ای برای ثبت اطلاعات، مسافران و بازبینی.',link('بازگشت به سفرها','/trips'))}<div class="stepper">${steps.map((s,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${step===i?'current':step>i?'done':''}"><span>${step>i?'✓':fmt(i+1)}</span>${s}</span>`).join('')}</div><div class="grid split">${panel(steps[step],`<div class="panel-body">${step===0?`<div class="field-grid">${input('واحد درخواست‌کننده','نام واحد…','منابع انسانی')}${input('تاریخ درخواست','۱۴۰۵/۰۷/۰۲','۱۴۰۵/۰۷/۰۲')}${input('شرح درخواست','موضوع سفر…','انتقال کارکنان','text','full')}</div><div class="info-note" style="margin-top:18px">شماره رسمی درخواست پس از ثبت در پروژه اصلی تخصیص می‌یابد.</div>`:step===1?`<h3 class="section-label">مسافران</h3><div class="field-grid">${input('مسافر اول','جست‌وجوی فرد…','مریم احمدی')}${input('زمان حرکت','ساعت','۰۹:۳۰')}${input('مبدا','جست‌وجوی مکان…','ساختمان مرکزی')}${input('مقصد','جست‌وجوی مکان…','فرودگاه مهرآباد')}${input('مسافر دوم','جست‌وجوی فرد…','علی رضایی')}${input('زمان حرکت','ساعت','۰۹:۳۰')}</div><div class="warning-note" style="margin-top:16px">هر مسافر مبدا، مقصد و ساعت مخصوص خود را دارد؛ مسیر پیشنهادی اختیاری است.</div>`:`<div class="field-grid">${field('واحد درخواست‌کننده','منابع انسانی')}${field('تاریخ درخواست','۱۴۰۵/۰۷/۰۲')}${field('مسافران','۲ نفر')}${field('مبدا','ساختمان مرکزی')}${field('مقصد','فرودگاه مهرآباد')}${field('ساعت حرکت','۰۹:۳۰')}</div><div class="info-note" style="margin-top:17px">بعد از ثبت، درخواست در وضعیت «جدید» وارد صف رسیدگی می‌شود.</div>`}</div><div class="footer-actions">${button(step?'مرحله قبل':'انصراف',step?'wizard-back':'wizard-cancel')}${button(step===2?'نمایش درخواست نمونه':'مرحله بعد',step===2?'wizard-finish':'wizard-next','primary')}</div>`)}${panel('پیش‌نمایش جریان',`<div class="panel-body"><div class="timeline"><div class="timeline-item"><b>ثبت درخواست</b><p>زمان و واحد درخواست‌کننده</p></div><div class="timeline-item"><b>مسافران</b><p>مبدا، مقصد و زمان برای هر نفر</p></div><div class="timeline-item"><b>بازبینی</b><p>کنترل اطلاعات قبل از ثبت</p></div></div><p class="subtext">این کانسپت داده‌ای ثبت نمی‌کند؛ دکمهٔ آخر پروندهٔ نمایشی را باز می‌کند.</p></div>`)}</div>`}
function stage(status){const stages=[['New','ثبت درخواست'],['Assigned','تخصیص'],['InProgress','اجرای سفر'],['Completed','تکمیل']];return `<div class="stage-row">${status==='Cancelled'?`<span class="stage cancelled">✕ لغوشده</span>`:stages.map(([key,label],i)=>{const current=stages.findIndex(s=>s[0]===status);return `${i?'<span class="flow-arrow">←</span>':''}<span class="stage ${i<current?'done':i===current?'current':''}">${i<current?'✓':fmt(i+1)} ${label}</span>`}).join('')}</div>`}
function workspace(){const t=demoTrips[state.tripIndex];const tabs=[['details','جزئیات سفر'],['passengers','مسافران'],['assignment','راننده و خودرو'],['route','مسیر'],['completion',t.status==='Cancelled'?'لغوشده':t.status==='Completed'?'تکمیل‌شده':'تکمیل']];return `${head('سفرها',`درخواست ${t.no}`,`${t.by} · ثبت‌شده در ${t.date}`,`${link('بازگشت به صف','/trips/handling')}${t.status!=='New'&&t.status!=='Cancelled'?link('برگه مأموریت','/trips/voucher'):' '}`)}<div class="panel" style="margin-bottom:15px"><div class="panel-body"><div class="detail-top"><div class="detail-title"><span class="big-icon">↗</span><div><h2>${t.from} ← ${t.to}</h2><small>${fmt(t.count)} مسافر · ${t.date}، ساعت ${t.time}</small></div></div>${badge(statusLabel[t.status],statusTone[t.status])}</div>${stage(t.status)}</div></div><div class="grid split"><section class="panel"><div class="tabs" role="tablist" aria-label="بخش‌های پرونده سفر">${tabs.map(([id,label])=>`<button class="tab ${state.tab===id?'active':''}" data-tab="${id}" role="tab" aria-selected="${state.tab===id}">${label}</button>`).join('')}</div><div class="panel-body">${tripTab(t)}</div></section>${panel('اقدام بعدی',`<div class="panel-body">${nextAction(t)}<hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h3 class="section-label">ردیابی وضعیت</h3><div class="timeline"><div class="timeline-item"><b>درخواست ثبت شد</b><p>${t.date} · ${t.by}</p></div>${t.status!=='New'?`<div class="timeline-item"><b>${t.status==='Cancelled'?'درخواست لغو شد':'تخصیص راننده و خودرو'}</b><p>${t.status==='Cancelled'?'بسته‌شدن پرونده':'علی رضایی · پژو ۲۰۷'}</p></div>`:''}${['InProgress','Completed'].includes(t.status)?'<div class="timeline-item"><b>سفر شروع شد</b><p>ثبت زمان حرکت واقعی</p></div>':''}${t.status==='Completed'?'<div class="timeline-item"><b>سفر تکمیل شد</b><p>زمان بازگشت ثبت شد</p></div>':''}</div><div class="inline-actions" style="margin-top:11px">${button('بازنشانی نمونه','reset-trip')}</div></div>`)}</div>`}
function nextAction(t){return t.status==='New'?`<div class="info-note">برای اعزام، ابتدا راننده و خودرو را به هر مسافر تخصیص دهید.</div><div class="inline-actions" style="margin-top:14px">${button('ثبت تخصیص نمونه','assign','primary')}${button('لغو درخواست','cancel','danger')}</div>`:t.status==='Assigned'?`<div class="warning-note">راننده و خودرو ثبت شده‌اند. پس از شروع سفر، امکان تغییر تخصیص وجود ندارد.</div><div class="inline-actions" style="margin-top:14px">${button('ثبت شروع سفر','start','primary')}${button('لغو پیش از شروع','cancel','danger')}</div>`:t.status==='InProgress'?`<div class="info-note">سفر در حال اجراست. پس از بازگشت، زمان پایان را ثبت کنید.</div><div class="inline-actions" style="margin-top:14px">${button('ثبت بازگشت و تکمیل','complete','primary')}</div>`:`<div class="${t.status==='Completed'?'info-note':'warning-note'}">پرونده ${statusLabel[t.status]} است و اقدام اجرایی دیگری ندارد.</div>`}
function tripTab(t){switch(state.tab){case 'details':return `<h3 class="section-label">اطلاعات درخواست</h3><div class="field-grid">${field('شماره درخواست',t.no)}${field('واحد',t.by)}${field('وضعیت',badge(statusLabel[t.status],statusTone[t.status]))}${field('تاریخ حرکت',t.date)}${field('ساعت حرکت',t.time)}${field('مسافران',fmt(t.count)+' نفر')}</div><h3 class="section-label" style="margin-top:25px">گردش کار</h3><p class="subtext">مراحل بعدی از بخش «اقدام بعدی» و تب‌های پرونده در دسترس‌اند.</p>`;case 'passengers':return `<h3 class="section-label">مسافران درخواست</h3>${Array.from({length:t.count},(_,i)=>`<div class="list-row"><span class="row-icon">${fmt(i+1)}</span><span class="row-copy"><b>${i===0?t.person:'علی رضایی'}</b><small>${t.from} ← ${t.to} · ${t.time}</small></span>${badge(i===0?'مسافر اصلی':'همراه','neutral')}</div>`).join('')}<p class="subtext" style="margin-top:14px">هر مسافر در مدل اصلی یک سفر جداگانه با مبدا، مقصد و اجرای مستقل دارد.</p>`;case 'assignment':return `<h3 class="section-label">راننده و خودرو</h3>${t.status==='New'?`<div class="warning-note">هنوز برای این درخواست تخصیصی ثبت نشده است.</div><div class="field-grid" style="margin-top:18px">${input('راننده واجد شرایط','جست‌وجوی راننده…','علی رضایی')}${input('خودرو','جست‌وجوی پلاک یا مدل…','پژو ۲۰۷')}</div><div class="inline-actions" style="margin-top:16px">${button('ثبت تخصیص نمونه','assign','primary')}</div>`:t.status==='Cancelled'?'<div class="empty">این درخواست لغو شده است.</div>':`<div class="field-grid">${field('راننده','علی رضایی')}${field('گواهینامه','پایه ۲ · معتبر')}${field('خودرو','پژو ۲۰۷')}${field('پلاک',plate(vehicles[0].plate))}${field('وضعیت تخصیص',badge('ثبت‌شده','green'))}${field('زمان شروع برنامه‌ای',t.date+' · '+t.time)}</div><div class="inline-actions" style="margin-top:18px">${link('مشاهده برگه مأموریت','/trips/voucher')}</div>`}`;case 'route':return `<h3 class="section-label">مسیر پیشنهادی</h3><div class="route-box"><div class="route-stop"><span>●</span><b>${t.from}</b><small>مبدا</small></div><div class="route-line"></div><div class="route-stop"><span>○</span><b>نقطه میانی</b><small>اختیاری</small></div><div class="route-line"></div><div class="route-stop"><span>◆</span><b>${t.to}</b><small>مقصد</small></div></div><div class="field-grid" style="margin-top:18px">${field('مسافت پیشنهادی','۲۱ کیلومتر')}${field('مدت پیشنهادی','۳۵ دقیقه')}${field('وضعیت مسیر',badge('اختیاری','neutral'))}</div><p class="subtext" style="margin-top:12px">در پروژه اصلی ثبت دستی مکان و مسیر بدون نقشه هم ممکن است.</p>`;default:return `<h3 class="section-label">${t.status==='Completed'?'خلاصه بازگشت':t.status==='Cancelled'?'درخواست لغوشده':'اجرای سفر و تکمیل'}</h3>${t.status==='Completed'?`<div class="field-grid">${field('شروع واقعی','۰۹:۳۸')}${field('پایان واقعی','۱۰:۲۲')}${field('وضعیت',badge('تکمیل‌شده','green'))}</div><p class="subtext">فرم نظرسنجی و اطلاعات اجرای هر مسافر در پروندهٔ اصلی ثبت می‌شوند.</p>`:t.status==='Cancelled'?'<div class="warning-note">لغو تنها پیش از شروع اجرای سفر ممکن است.</div>':`<div class="info-note">اطلاعات اجرای واقعی بعد از اعزام ثبت می‌شود. وضعیت کنونی: ${statusLabel[t.status]}.</div>${nextAction(t)}`}`}}
function voucher(){const t=demoTrips[state.tripIndex];return `${head('سفرها','برگه مأموریت سفر — نسخه راننده',`مربوط به درخواست ${t.no}؛ پیش‌نمایش چیدمان چاپی.`,`${link('بازگشت به پرونده','/trips/workspace')}${button('چاپ پیش‌نمایش','print')}`)}<section class="panel" style="max-width:850px;margin:auto"><div class="panel-body" style="padding:32px"><div class="detail-top"><div><div class="page-kicker">FleetManagement / برگه مأموریت</div><h2 style="margin:5px 0">${t.no}</h2></div>${badge('نسخه نمایشی','neutral')}</div><hr style="border:0;border-top:1px solid var(--line);margin:21px 0"><div class="field-grid">${field('راننده','علی رضایی')}${field('خودرو','پژو ۲۰۷')}${field('پلاک',plate(vehicles[0].plate))}${field('تاریخ مأموریت',t.date)}${field('زمان حرکت',t.time)}${field('تعداد مسافران',fmt(t.count))}${field('مبدا',t.from)}${field('مقصد',t.to)}${field('وضعیت',badge(statusLabel[t.status],statusTone[t.status]))}</div><div class="warning-note" style="margin-top:27px">این برگه فقط نمونهٔ طراحی است و سند رسمی برای مأموریت واقعی نیست.</div></div></section>`}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3600)}
window.addEventListener('hashchange',()=>{state.search='';state.filter='all';render()});
document.addEventListener('click',e=>{const t=e.target.closest('[data-action],[data-tab],[data-trip],[data-catalog]');if(!t)return;if(t.dataset.trip!==undefined)state.tripIndex=Number(t.dataset.trip);if(t.dataset.tab){state.tab=t.dataset.tab;render();return}if(t.dataset.catalog){state.catalog=t.dataset.catalog;render();return}const a=t.dataset.action;if(!a)return;const trip=demoTrips[state.tripIndex];if(a==='assign'&&trip.status==='New'){trip.status='Assigned';state.tab='assignment';toast('در نمونه، تخصیص ثبت شد.')}else if(a==='start'&&trip.status==='Assigned'){trip.status='InProgress';state.tab='completion';toast('در نمونه، سفر شروع شد.')}else if(a==='complete'&&trip.status==='InProgress'){trip.status='Completed';state.tab='completion';toast('در نمونه، سفر تکمیل شد.')}else if(a==='cancel'&&['New','Assigned'].includes(trip.status)){trip.status='Cancelled';state.tab='completion';toast('در نمونه، درخواست لغو شد.')}else if(a==='reset-trip'){demoTrips[state.tripIndex].status=['New','Assigned','InProgress','Completed','Cancelled'][state.tripIndex];state.tab='details';toast('وضعیت نمونه بازنشانی شد.')}else if(a==='wizard-next')state.wizard=Math.min(2,state.wizard+1);else if(a==='wizard-back')state.wizard=Math.max(0,state.wizard-1);else if(a==='wizard-cancel'){location.hash='#/trips';return}else if(a==='wizard-finish'){state.tripIndex=0;state.tab='details';location.hash='#/trips/workspace';return}else if(a==='print'){window.print();return}else if(a==='sample-save')toast('این فرم نمایشی است؛ داده‌ای ذخیره نشد.');else if(a==='filter-info')toast('از جست‌وجو و فیلتر وضعیت برای محدودکردن فهرست استفاده کنید.');render()});
document.addEventListener('input',e=>{if(e.target.matches('[data-search]')){const pos=e.target.selectionStart;state.search=e.target.value;const old=document.activeElement;const area=$('#view');const scroll=window.scrollY;area.innerHTML=({'/people':peopleList,'/fleet/vehicles':vehicleList,'/fleet/insurances':insuranceList,'/drivers':driverList,'/trips/requests':()=>tripList(false),'/trips/handling':()=>tripList(true)})[state.route]?.()||area.innerHTML;const field=$('[data-search]');if(field){field.focus();field.setSelectionRange(pos,pos)}window.scrollTo(0,scroll)}});
document.addEventListener('change',e=>{if(e.target.matches('[data-filter]')){state.filter=e.target.value;const scroll=window.scrollY;$('#view').innerHTML=tripList(state.route==='/trips/handling');window.scrollTo(0,scroll)}});
$('#theme-toggle').onclick=()=>{state.theme=state.theme==='light'?'dark':'light';setTheme()};$('#menu-toggle').onclick=()=>{$('#sidebar').classList.add('open');$('#scrim').classList.add('show')};$('#scrim').onclick=()=>{$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show')};$('#ribbon-close').onclick=()=>$('.concept-ribbon').remove();$('#top-date').textContent=new Intl.DateTimeFormat('fa-IR',{dateStyle:'long',timeZone:'Asia/Tehran'}).format(new Date());if(!location.hash)location.hash='#/trips/handling';render();
